import { Component, Event, EventEmitter, Prop, State, Watch, h } from '@stencil/core';

@Component({
  tag: 'std-password-validation',
  styleUrl: 'std-password-validation.css',
  shadow: true
})
export class StdPasswordValidationComponent {
  @Prop() password: string;

  @Event() status: EventEmitter;

  @State() hasLowercase: boolean;
  @State() hasUppercase: boolean;
  @State() hasNumber: boolean;
  @State() isValidLength: boolean;
  @State() completed: number;

  @Watch('password')
  validatePassword(newValue: string) {
    this.hasLowercase = /(?=.*[a-z])/.test(newValue);
    this.hasUppercase = /(?=.*[A-Z])/.test(newValue);
    this.hasNumber = /(?=.*\d)/.test(newValue);
    this.isValidLength = /.{8,}/.test(newValue);
    this.completed = +this.hasLowercase + +this.hasUppercase + +this.hasNumber + +this.isValidLength;
    this.status.emit(this.completed);
  }

  render() {
    const _ = this.completed;
    const passwordSetted = (this.password || '').length == 8;
    const crossedText = 'text-soft line-through';
    const _bg = ['bg-alternative-medium', 'bg-secondary-yellow', 'bg-green-medium', 'bg-success'];
    const bullet = [
      'icon-close text-2xl leading-none text-error',
      'block w-2 h-2 rounded-full border border-border-default',
      'icon-checkmark-2px text-2xl leading-none text-success'
    ];

    return (
      <div class="flex flex-col gap-4">
        <h4 class="text-sm font-sans font-bold">Tu contraseña debe tener:</h4>
        <ul class="flex gap-2">
          <li class={`w-full h-0.5 ${_ == 4 ? _bg[3] : _ >= 1 ? _bg[1] : _bg[0]}`}></li>
          <li class={`w-full h-0.5 ${_ == 4 ? _bg[3] : _ >= 2 ? _bg[1] : _bg[0]}`}></li>
          <li class={`w-full h-0.5 ${_ == 4 ? _bg[3] : _ >= 3 ? _bg[2] : _bg[0]}`}></li>
          <li class={`w-full h-0.5 ${_ == 4 ? _bg[3] : _ >= 4 ? _bg[3] : _bg[0]}`}></li>
        </ul>
        <ul class="text-sm">
          <li class="flex items-center">
            <span class="flex justify-center items-center w-6 h-6 rounded-full bg-white">
              <i class={passwordSetted && !this.hasLowercase ? bullet[0] : this.hasLowercase ? bullet[2] : bullet[1]}></i>
            </span>
            <span class={this.hasLowercase && crossedText}>Al menos una minúscula</span>
          </li>
          <li class="flex items-center">
            <span class="flex justify-center items-center w-6 h-6 rounded-full bg-white">
              <i class={passwordSetted && !this.hasUppercase ? bullet[0] : this.hasUppercase ? bullet[2] : bullet[1]}></i>
            </span>
            <span class={this.hasUppercase && crossedText}>Al menos una mayúscula</span>
          </li>
          <li class="flex items-center">
            <span class="flex justify-center items-center w-6 h-6 rounded-full bg-white">
              <i class={passwordSetted && !this.hasNumber ? bullet[0] : this.hasNumber ? bullet[2] : bullet[1]}></i>
            </span>
            <span class={this.hasNumber && crossedText}>Al menos un número</span>
          </li>
          <li class="flex items-center">
            <span class="flex justify-center items-center w-6 h-6 rounded-full bg-white">
              <i class={passwordSetted && !this.isValidLength ? bullet[0] : this.isValidLength ? bullet[2] : bullet[1]}></i>
            </span>
            <span class={this.isValidLength && crossedText}>8 caracteres</span>
          </li>
        </ul>
      </div>
    );
  }
}
